L"\n"
L"function setStaticLabels() {\n"
L"  const value = labels();\n"
L"  document.getElementById('feels-label').textContent = value.feels;\n"
L"  document.getElementById('humidity-label').textContent = value.humidity;\n"
L"  document.getElementById('wind-label').textContent = value.wind;\n"
L"  document.getElementById('precip-label').textContent = value.precip;\n"
L"  document.getElementById('visibility-label').textContent = value.visibility;\n"
L"  document.getElementById('minute-title').textContent = value.next2h;\n"
L"  document.getElementById('hourly-title').textContent = value.hourly24;\n"
L"  document.getElementById('air-title').textContent = value.air;\n"
L"  document.getElementById('daily-title').textContent = value.daily5;\n"
L"  elements.minuteLead.textContent = value.minuteHint;\n"
L"  elements.hourlyLead.textContent = value.hourlyHint;\n"
L"  elements.dailyLead.textContent = value.dailyHint;\n"
L"  updateThemeControl();\n"
L"  updateRefreshControl();\n"
L"}\n"
L"\n"
L"function openMeteoCondition(code) {\n"
L"  const zh = isChinese();\n"
L"  const map = zh ? {\n"
L"    0: '\\u6674', 1: '\\u5927\\u90e8\\u6674\\u6717', 2: '\\u591a\\u4e91', 3: '\\u9634',\n"
L"    45: '\\u96fe', 48: '\\u51bb\\u96fe', 51: '\\u5c0f\\u96e8', 53: '\\u5c0f\\u96e8', 55: '\\u4e2d\\u96e8',\n"
L"    56: '\\u51bb\\u96e8', 57: '\\u51bb\\u96e8', 61: '\\u5c0f\\u96e8', 63: '\\u4e2d\\u96e8',\n"
L"    65: '\\u5927\\u96e8', 66: '\\u51bb\\u96e8', 67: '\\u51bb\\u96e8', 71: '\\u5c0f\\u96ea',\n"
L"    73: '\\u4e2d\\u96ea', 75: '\\u5927\\u96ea', 77: '\\u96ea\\u7c92', 80: '\\u9635\\u96e8',\n"
L"    81: '\\u9635\\u96e8', 82: '\\u5f3a\\u9635\\u96e8', 85: '\\u9635\\u96ea', 86: '\\u5f3a\\u9635\\u96ea',\n"
L"    95: '\\u96f7\\u96e8', 96: '\\u96f7\\u96e8\\u4f34\\u51b0\\u96f9', 99: '\\u96f7\\u96e8\\u4f34\\u51b0\\u96f9'\n"
L"  } : {\n"
L"    0: 'Clear', 1: 'Mainly clear', 2: 'Partly cloudy', 3: 'Overcast', 45: 'Fog',\n"
L"    48: 'Freezing fog', 51: 'Drizzle', 53: 'Drizzle', 55: 'Rain', 56: 'Freezing drizzle',\n"
L"    57: 'Freezing drizzle', 61: 'Light rain', 63: 'Rain', 65: 'Heavy rain', 66: 'Freezing rain',\n"
L"    67: 'Freezing rain', 71: 'Light snow', 73: 'Snow', 75: 'Heavy snow', 77: 'Snow grains',\n"
L"    80: 'Rain showers', 81: 'Rain showers', 82: 'Heavy rain showers', 85: 'Snow showers',\n"
L"    86: 'Heavy snow showers', 95: 'Thunderstorm', 96: 'Thunderstorm with hail', 99: 'Thunderstorm with hail'\n"
L"  };\n"
L"  return map[Number(code)] || (zh ? '\\u672a\\u77e5\\u5929\\u6c14' : 'Unknown weather');\n"
L"}\n"
L"\n"
L"function weatherText(item, provider) {\n"
L"  return textValue(item && item.text) || (provider === 'qweather'\n"
L"    ? (isChinese() ? '\\u672a\\u77e5\\u5929\\u6c14' : 'Unknown weather')\n"
L"    : openMeteoCondition(item && item.code));\n"
L"}\n"
L"\n"
L"function formatTime(value, withDate = false) {\n"
L"  if (!value) return '';\n"
L"  try {\n"
L"    const options = withDate\n"
L"      ? { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' }\n"
L"      : { hour: '2-digit', minute: '2-digit' };\n"
L"    return new Intl.DateTimeFormat(state.language || 'en-US', options).format(new Date(value));\n"
L"  } catch (error) {\n"
L"    const match = textValue(value).match(/(?:T|\\s)([0-9]{2}:[0-9]{2})/);\n"
L"    return match ? match[1] : textValue(value);\n"
L"  }\n"
L"}\n"
L"\n"
L"function tempUnit() {\n"
L"  return `${String.fromCharCode(176)}${state.unit ? 'F' : 'C'}`;\n"
L"}\n"
L"\n"
L"function displayTemperatureValue(value) {\n"
L"  if (value === null || value === undefined || !Number.isFinite(Number(value))) return null;\n"
L"  const celsius = Number(value);\n"
L"  return state.unit ? celsius * 9 / 5 + 32 : celsius;\n"
L"}\n"
L"\n"
L"function formatTemperature(value) {\n"
L"  const display = displayTemperatureValue(value);\n"
L"  return display === null ? '--' : `${Math.round(display)}${tempUnit()}`;\n"
L"}\n"
L"\n"
L"function formatTemperatureShort(value) {\n"
L"  const display = displayTemperatureValue(value);\n"
L"  return display === null ? '--' : `${Math.round(display)}${String.fromCharCode(176)}`;\n"
L"}\n"
L"\n"
L"function formatNumber(value, suffix, digits = 0) {\n"
L"  if (value === null || value === undefined || !Number.isFinite(Number(value))) return '--';\n"
L"  return `${Number(value).toFixed(digits)}${suffix || ''}`;\n"
L"}\n"
L"\n"
L"function formatMeasurementUnit(value) {\n"
L"  const unit = textValue(value);\n"
L"  if (/^(?:u|\\u03bc|\\u00b5)g\\/m(?:3|\\u00b3)$/i.test(unit)) return '\\u00b5g/m\\u00b3';\n"
L"  if (/^mg\\/m(?:3|\\u00b3)$/i.test(unit)) return 'mg/m\\u00b3';\n"
L"  return unit;\n"
L"}\n"
L"\n"
L"function formatWindDirection(value) {\n"
L"  const direction = textValue(value);\n"
L"  if (!isChinese()) return direction.toUpperCase();\n"
L"  const names = {\n"
L"    n: '\\u5317\\u98ce', nne: '\\u5317\\u4e1c\\u5317\\u98ce', ne: '\\u4e1c\\u5317\\u98ce', ene: '\\u4e1c\\u4e1c\\u5317\\u98ce',\n"
L"    e: '\\u4e1c\\u98ce', ese: '\\u4e1c\\u4e1c\\u5357\\u98ce', se: '\\u4e1c\\u5357\\u98ce', sse: '\\u5357\\u4e1c\\u5357\\u98ce',\n"
L"    s: '\\u5357\\u98ce', ssw: '\\u5357\\u897f\\u5357\\u98ce', sw: '\\u897f\\u5357\\u98ce', wsw: '\\u897f\\u897f\\u5357\\u98ce',\n"
L"    w: '\\u897f\\u98ce', wnw: '\\u897f\\u897f\\u5317\\u98ce', nw: '\\u897f\\u5317\\u98ce', nnw: '\\u5317\\u897f\\u5317\\u98ce',\n"
L"    none: '\\u65e0\\u6301\\u7eed\\u98ce\\u5411', vrb: '\\u98ce\\u5411\\u4e0d\\u5b9a'\n"
L"  };\n"
L"  return names[direction.toLowerCase()] || direction;\n"
L"}\n"
L"\n"
L"function currentSource() {\n"
L"  const qDataset = state.datasets.current;\n"
L"  const qCurrent = qDataset && qDataset.data;\n"
L"  if (qCurrent && qCurrent.temp !== null) {\n"
L"    return { item: qCurrent, provider: 'qweather', fetchedAt: qDataset.fetchedAt };\n"
L"  }\n"
L"  const fallback = state.fallback && state.fallback.data && state.fallback.data.current;\n"
L"  return fallback && fallback.temp !== null\n"
L"    ? { item: fallback, provider: 'open-meteo', fetchedAt: state.fallback.fetchedAt }\n"
L"    : null;\n"
L"}\n"
L"\n"
L"function hourlySource() {\n"
L"  if (state.mode === 'qweather') {\n"
L"    return { rows: state.datasets.hourly && state.datasets.hourly.data || [], provider: 'qweather' };\n"
L"  }\n"
L"  return { rows: state.fallback && state.fallback.data.hourly || [], provider: 'open-meteo' };\n"
L"}\n"
L"\n"
L"function dailySource() {\n"
L"  if (state.mode === 'qweather') {\n"
L"    return { rows: state.datasets.daily && state.datasets.daily.data || [], provider: 'qweather' };\n"
L"  }\n"
L"  return { rows: state.fallback && state.fallback.data.daily || [], provider: 'open-meteo' };\n"
L"}\n"
L"\n"
L"function hasCurrentData() {\n"
L"  return currentSource() !== null;\n"
L"}\n"
L"\n"
L"function automaticLocationLabel() {\n"
L"  const value = labels();\n"
L"  if (state.locationMode === LOCATION_MODE_DIRECT_IP) return value.directIpLocation;\n"
L"  if (state.locationMode === LOCATION_MODE_MANUAL) return value.manualLocationError;\n"
L"  return value.windowsLocation;\n"
L"}\n"
L"\n"
L"function automaticLocationErrorLabel() {\n"
L"  const value = labels();\n"
L"  if (state.locationMode === LOCATION_MODE_DIRECT_IP) return value.directIpError;\n"
L"  if (state.locationMode === LOCATION_MODE_MANUAL) return value.manualLocationError;\n"
L"  return value.windowsLocationError;\n"
L"}\n"
L"\n"
L"function setLoading() {\n"
L"  const value = labels();\n"
L"  setStaticLabels();\n"
L"  document.documentElement.lang = state.language || 'en';\n"
L"  elements.location.textContent = state.location || automaticLocationLabel();\n"
L"  elements.resolved.textContent = '';\n"
L"  elements.providerState.textContent = '';\n"
L"  elements.providerState.classList.remove('warning');\n"
L"  elements.updateStatus.textContent = '';\n"
L"  elements.condition.textContent = value.loading;\n"
L"  elements.temperature.textContent = '--';\n"
L"  elements.unit.textContent = tempUnit();\n"
L"  elements.updated.textContent = '';\n"
L"  elements.heroRange.textContent = '';\n"
L"  elements.heroRange.hidden = true;\n"
L"  elements.heroSummary.textContent = '';\n"
L"  elements.heroSummary.hidden = true;\n"
L"  elements.heroContext.textContent = '';\n"
L"  elements.heroContext.hidden = true;\n"
L"  elements.feels.textContent = '--';\n"
L"  elements.feelsSub.textContent = '';\n"
L"  elements.humidity.textContent = '--';\n"
L"  elements.humidityMeter.style.width = '0%';\n"
L"  elements.humiditySub.textContent = '';\n"
L"  elements.wind.textContent = '--';\n"
L"  elements.windSub.textContent = '';\n"
L"  elements.precip.textContent = '--';\n"
L"  elements.precipSub.textContent = '';\n"
L"  elements.visibility.textContent = '--';\n"
L"  elements.visibilitySub.textContent = '';\n"
L"  elements.alerts.hidden = true;\n"
L"  elements.alerts.replaceChildren();\n"
L"  elements.minuteSection.hidden = true;\n"
L"  elements.minuteDot.classList.remove('is-raining');\n"
L"  elements.minuteThresholdHeavy.textContent = '';\n"
L"  elements.minuteThresholdLight.textContent = '';\n"
L"  elements.airSection.hidden = true;\n"
L"  elements.airLead.textContent = '';\n"
L"  elements.aqiScaleDot.style.left = '0%';\n"
L"  elements.airAdvice.textContent = '';\n"
L"  elements.airAdvice.hidden = true;\n"
L"  elements.hourly.replaceChildren();\n"
L"  elements.hourlyLead.textContent = value.hourlyHint;\n"
L"  elements.forecast.replaceChildren();\n"
L"  alertsRenderSignature = '';\n"
L"  setWeatherGlyph(elements.currentGlyph, { code: '999', isDay: 1 }, 'qweather');\n"
L"  elements.currentGlyph.setAttribute('aria-label', value.loading);\n"
L"  drawWeatherIcon(elements.currentIcon, { code: '999', isDay: 1 }, 'qweather');\n"
L"  updateRefreshControl();\n"
L"}\n"
L"\n"
L"function setError() {\n"
L"  setLoading();\n"
L"  const value = labels();\n"
L"  elements.condition.textContent = state.location ? value.error : automaticLocationErrorLabel();\n"
L"  elements.providerState.textContent = state.apiHost ? labels().fallback : 'Open-Meteo';\n"
L"  elements.providerState.classList.add('warning');\n"
L"}\n"
L"\n"
L"function renderProviderState() {\n"
L"  const value = labels();\n"
L"  elements.providerState.classList.remove('warning');\n"
L"  if (state.qAuthFailed) {\n"
L"    elements.providerState.textContent = state.mode === 'qweather'\n"
L"      ? `${value.authFailed} | ${value.lastData}`\n"
L"      : `${value.authFailed} | ${value.fallback}`;\n"
L"    elements.providerState.classList.add('warning');\n"
L"  } else if (state.mode === 'qweather') {\n"
L"    const hasErrors = Object.keys(state.errors).some((name) => name !== 'fallback');\n"
L"    elements.providerState.textContent = hasErrors ? `${value.qweather} | ${value.partial}` : value.qweather;\n"
L"    elements.providerState.classList.toggle('warning', hasErrors);\n"
L"  } else if (state.apiHost) {\n"
L"    elements.providerState.textContent = value.fallback;\n"
L"    elements.providerState.classList.add('warning');\n"
L"  } else {\n"
L"    elements.providerState.textContent = 'Open-Meteo';\n"
L"  }\n"
L"}\n"
L"\n"
L"function effectiveTheme() {\n"
L"  const explicit = document.documentElement.getAttribute('data-theme');\n"
L"  if (explicit === 'dark' || explicit === 'light') return explicit;\n"
L"  try {\n"
L"    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';\n"
L"  } catch (error) {\n"
L"    return 'light';\n"
L"  }\n"
L"}\n"
L"\n"
L"function updateThemeControl() {\n"
L"  if (!elements.themeButton) return;\n"
L"  const dark = effectiveTheme() === 'dark';\n"
L"  const value = labels();\n"
L"  const label = dark ? value.switchToLight : value.switchToDark;\n"
L"  const icon = elements.themeButton.querySelector('.control-icon');\n"
L"  if (icon) icon.textContent = dark ? '\\u2600' : '\\u263e';\n"
L"  elements.themeButton.dataset.themeMode = dark ? 'dark' : 'light';\n"
L"  elements.themeButton.title = label;\n"
L"  elements.themeButton.setAttribute('aria-label', label);\n"
L"  elements.themeButton.setAttribute('aria-pressed', dark ? 'true' : 'false');\n"
L"}\n"
L"\n"
L"function updateRefreshControl() {\n"
L"  if (!elements.refreshButton) return;\n"
L"  const value = labels();\n"
L"  const icon = elements.refreshButton.querySelector('.control-icon');\n"
L"  if (icon) icon.textContent = '\\u21bb';\n"
L"  const remaining = Math.max(0, manualRefreshCooldownUntil - Date.now());\n"
L"  const disabled = manualRefreshInFlight || !state.coords || state.status !== 'ready' || remaining > 0;\n"
L"  elements.refreshButton.disabled = disabled;\n"
L"  elements.refreshButton.classList.toggle('is-busy', manualRefreshInFlight);\n"
L"  elements.refreshButton.setAttribute('aria-busy', manualRefreshInFlight ? 'true' : 'false');\n"
L"  const label = manualRefreshInFlight\n"
L"    ? value.refreshing\n"
L"    : remaining > 0 ? value.refreshDeferred : value.refresh;\n"
L"  elements.refreshButton.title = label;\n"
L"  elements.refreshButton.setAttribute('aria-label', label);\n"
L"  if (manualRefreshCooldownTimer) {\n"
L"    clearTimeout(manualRefreshCooldownTimer);\n"
L"    manualRefreshCooldownTimer = null;\n"
L"  }\n"
L"  if (!manualRefreshInFlight && remaining > 0) {\n"
L"    manualRefreshCooldownTimer = setTimeout(() => {\n"
L"      manualRefreshCooldownTimer = null;\n"
L"      updateRefreshControl();\n"
L"    }, remaining + 10);\n"
L"  }\n"
L"}\n"
L"\n"
L"function setRefreshNotice(message) {\n"
L"  refreshNotice = textValue(message);\n"
L"  refreshNoticeUntil = Date.now() + 1800;\n"
L"  if (refreshNoticeTimer) clearTimeout(refreshNoticeTimer);\n"
L"  refreshNoticeTimer = setTimeout(() => {\n"
L"    refreshNoticeTimer = null;\n"
L"    refreshNotice = '';\n"
L"    refreshNoticeUntil = 0;\n"
L"    renderUpdateStatus(currentSource());\n"
L"  }, 1800);\n"
L"  renderUpdateStatus(currentSource());\n"
L"}\n"
L"\n"
L"function renderUpdateStatus(current) {\n"
L"  if (!elements.updateStatus) return;\n"
L"  const value = labels();\n"
L"  if (manualRefreshInFlight) {\n"
L"    elements.updateStatus.textContent = value.refreshing;\n"
L"    return;\n"
L"  }\n"
L"  if (refreshNotice && Date.now() < refreshNoticeUntil) {\n"
L"    elements.updateStatus.textContent = refreshNotice;\n"
L"    return;\n"
L"  }\n"
L"  const item = current && current.item;\n"
L"  const updateTime = item && item.time || current && current.fetchedAt;\n"
L"  elements.updateStatus.textContent = updateTime ? value.updated + ' ' + formatTime(updateTime) : '';\n"
L"}\n"
L"\n"
L"function notifyNativeTheme(theme) {\n"
L"  try {\n"
L"    if (window.chrome && window.chrome.webview) {\n"
L"      window.chrome.webview.postMessage(theme === 'dark'\n"
L"        ? 'ep_weather_theme_dark'\n"
L"        : 'ep_weather_theme_light');\n"
L"    }\n"
L"  } catch (error) {\n"
L"    // Standalone previews do not provide the native WebView host.\n"
L"  }\n"
L"}\n"
L"\n"
L"function toggleTheme() {\n"
L"  const next = effectiveTheme() === 'dark' ? 'light' : 'dark';\n"
L"  document.documentElement.setAttribute('data-theme', next);\n"
L"  updateThemeControl();\n"
L"  notifyNativeTheme(next);\n"
L"}\n"
L"\n"
L"async function refreshWeatherNow() {\n"
L"  const value = labels();\n"
L"  const now = Date.now();\n"
L"  if (manualRefreshInFlight || !state.coords || now < manualRefreshCooldownUntil) return false;\n"
L"  manualRefreshInFlight = true;\n"
L"  manualRefreshCooldownUntil = now + MANUAL_REFRESH_COOLDOWN;\n"
L"  updateRefreshControl();\n"
L"  renderUpdateStatus(currentSource());\n"
L"  try {\n"
L"    const changed = await refreshDue(true);\n"
L"    setRefreshNotice(changed ? value.refreshDone : value.refreshDeferred);\n"
L"    return Boolean(changed);\n"
L"  } catch (error) {\n"
L"    setRefreshNotice(value.refreshFailed);\n"
L"    return false;\n"
L"  } finally {\n"
L"    manualRefreshInFlight = false;\n"
L"    updateRefreshControl();\n"
L"    renderUpdateStatus(currentSource());\n"
L"  }\n"
L"}\n"
L"\n"
L"function alertColor(alert) {\n"
L"  const rawColor = alert.color && typeof alert.color === 'object'\n"
L"    ? textValue(pick(alert.color, ['code', 'name']))\n"
L"    : textValue(alert.color);\n"
L"  const value = `${alert.severity} ${alert.title} ${rawColor}`.toLowerCase();\n"
L"  if (/red|extreme|severe|\\u7ea2|\\u7279\\u522b\\u4e25\\u91cd/.test(value)) return '#b3261e';\n"
L"  if (/orange|moderate|\\u6a59|\\u4e25\\u91cd/.test(value)) return '#c55318';\n"
L"  if (/yellow|minor|\\u9ec4|\\u8f83\\u91cd/.test(value)) return '#9a6500';\n"
L"  if (/blue|\\u84dd|\\u4e00\\u822c/.test(value)) return '#286fa8';\n"
L"  return '#b3261e';\n"
L"}\n"
L"\n"
L"function alertLevelText(alert) {\n"
L"  const rawColor = alert.color && typeof alert.color === 'object'\n"
L"    ? textValue(pick(alert.color, ['code', 'name'])).toLowerCase()\n"
L"    : textValue(alert.color).toLowerCase();\n"
L"  if (isChinese()) {\n"
L"    const colorNames = { red: '\\u7ea2\\u8272', orange: '\\u6a59\\u8272', yellow: '\\u9ec4\\u8272', blue: '\\u84dd\\u8272', white: '\\u767d\\u8272' };\n"
L"    if (colorNames[rawColor]) return colorNames[rawColor];\n"
L"  }\n"
L"  return textValue(alert.severity) || rawColor || labels().officialAlert;\n"
L"}\n"
L"\n"
L"function alertBlock(label, content) {\n"
L"  if (!content) return null;\n"
L"  const block = document.createElement('div');\n"
L"  block.className = 'alert-block';\n"
L"  const heading = document.createElement('strong');\n"
L"  heading.textContent = label;\n"
L"  const text = document.createElement('div');\n"
L"  text.textContent = content;\n"
L"  block.append(heading, text);\n"
L"  return block;\n"
L"}\n"
L"\n"
L"function alertIdentity(alert, index) {\n"
L"  const id = textValue(alert && alert.id);\n"
L"  if (id) return `id:${id}`;\n"
L"  const fallback = [\n"
L"    alert && alert.type,\n"
L"    alert && alert.title,\n"
L"    alert && alert.published,\n"
L"    alert && alert.start,\n"
L"    alert && alert.end\n"
L"  ].map((value) => textValue(value)).join('|');\n"
L"  return fallback || `index:${index}`;\n"
L"}\n"
L"\n"
L"function renderAlerts() {\n"
L"  const value = labels();\n"
L"  const data = state.mode === 'qweather' && state.datasets.alerts && state.datasets.alerts.data;\n"
L"  const alerts = data && Array.isArray(data.items) ? data.items : [];\n"
L"  const entries = alerts.map((alert, index) => ({ alert, key: alertIdentity(alert, index) }));\n"
L"  const signature = JSON.stringify([\n"
L"    state.generation,\n"
L"    state.language,\n"
L"    entries.map(({ alert, key }) => [\n"
L"      key,\n"
L"      alertColor(alert),\n"
L"      alertLevelText(alert),\n"
L"      alert.title,\n"
L"      alert.type,\n"
L"      alert.sender,\n"
L"      alert.published,\n"
L"      alert.start,\n"
L"      alert.end,\n"
L"      alert.description,\n"
L"      alert.standard,\n"
L"      alert.instruction\n"
L"    ].map((field) => textValue(field)))\n"
L"  ]);\n"
L"  if (signature === alertsRenderSignature && elements.alerts.childElementCount === entries.length) return;\n"
L"  alertsRenderSignature = signature;\n"
L"  const previousState = new Map(state.alertOpenStates);\n"
L"  for (const details of elements.alerts.querySelectorAll('details.alert[data-alert-key]')) {\n"
L"    previousState.set(details.dataset.alertKey, details.open);\n"
L"  }\n"
L"  const activeKeys = new Set(entries.map(({ key }) => key));\n"
L"  for (const key of state.alertOpenStates.keys()) {\n"
L"    if (!activeKeys.has(key)) state.alertOpenStates.delete(key);\n"
L"  }\n"
L"  elements.alerts.replaceChildren();\n"
L"  elements.alerts.hidden = alerts.length === 0;\n"
L"  for (const { alert, key } of entries) {\n"
L"    const details = document.createElement('details');\n"
L"    const color = alertColor(alert);\n"
L"    const open = previousState.has(key)\n"
L"      ? previousState.get(key)\n"
L"      : color === '#b3261e' || color === '#c55318';\n"
L"    details.className = 'alert';\n"
L"    details.dataset.alertKey = key;\n"
L"    details.style.setProperty('--alert-color', color);\n"
L"    details.open = open;\n"
L"    state.alertOpenStates.set(key, open);\n"
L"    const summary = document.createElement('summary');\n"
L"    const level = document.createElement('span');\n"
L"    level.className = 'alert-level';\n"
L"    level.textContent = alertLevelText(alert);\n"
L"    const title = document.createElement('span');\n"
L"    title.className = 'alert-title';\n"
L"    title.textContent = alert.title || alert.type || value.officialAlert;\n"
L"    const time = document.createElement('span');\n"
L"    time.className = 'alert-time';\n"
L"    time.textContent = formatTime(alert.published, true);\n"
L"    summary.append(level, title, time);\n"
L"    const body = document.createElement('div');\n"
L"    body.className = 'alert-body';\n"
L"    const meta = document.createElement('div');\n"
L"    meta.className = 'alert-meta';\n"
L"    const metaParts = [];\n"
L"    if (alert.sender) metaParts.push(`${value.publisher}: ${alert.sender}`);\n"
L"    const period = [formatTime(alert.start, true), formatTime(alert.end, true)].filter(Boolean).join(' - ');\n"
L"    if (period) metaParts.push(`${value.validUntil}: ${period}`);\n"
L"    meta.textContent = metaParts.join(' | ');\n"
L"    if (meta.textContent) body.append(meta);\n"
L"    for (const block of [\n"
L"      alertBlock(value.details, alert.description),\n"
L"      alertBlock(value.standard, alert.standard),\n"
L"      alertBlock(value.instruction, alert.instruction)\n"
L"    ]) if (block) body.append(block);\n"
L"    details.append(summary, body);\n"
L"    // Capture the intended state before the native details click action completes.\n"
L"    summary.addEventListener('click', () => {\n"
L"      state.alertOpenStates.set(key, !details.open);\n"
L"    });\n"
L"    details.addEventListener('toggle', () => {\n"
L"      if (elements.alerts.contains(details)) state.alertOpenStates.set(key, details.open);\n"
L"    });\n"
L"    elements.alerts.append(details);\n"
L"  }\n"
L"}\n"
L"\n"
L"function renderMinuteForecast() {\n"
L"  const value = labels();\n"
L"  const minute = state.mode === 'qweather' && state.datasets.minutely && state.datasets.minutely.data;\n"
L"  if (!minute) {\n"
L"    elements.minuteSection.hidden = true;\n"
L"    return;\n"
L"  }\n"
L"  elements.minuteSection.hidden = false;\n"
L"  elements.minuteLead.textContent = value.minuteHint;\n"
L"  if (minute.available === false) {\n"
L"    elements.minuteUpdated.textContent = '';\n"
L"    elements.minuteSummary.textContent = value.unavailable;\n"
L"    elements.minuteSummary.classList.remove('is-raining');\n"
L"    elements.minuteDot.classList.remove('is-raining');\n"
L"    elements.minuteThresholdHeavy.textContent = '';\n"
L"    elements.minuteThresholdLight.textContent = '';\n"
L"    elements.minuteChart.replaceChildren();\n"
L"    elements.minuteAxis.replaceChildren();\n"
L"    return;\n"
L"  }\n"
L"  elements.minuteUpdated.textContent = [value.minutePoints, formatTime(minute.updated)].filter(Boolean).join(' | ');\n"
L"  const points = Array.isArray(minute.points) ? minute.points.slice(0, 24) : [];\n"
L"  const raining = points.some((point) => Number(point.precip) > 0);\n"
L"  elements.minuteSummary.textContent = minute.summary || (raining ? value.next2h : value.noRain);\n"
L"  elements.minuteSummary.classList.toggle('is-raining', raining);\n"
L"  elements.minuteDot.classList.toggle('is-raining', raining);\n"
L"  elements.minuteThresholdHeavy.textContent = value.moderateRain + ' >= 0.15 mm';\n"
L"  elements.minuteThresholdLight.textContent = value.lightRain + ' >= 0.05 mm';\n"
L"  elements.minuteChart.replaceChildren();\n"
L"  const max = Math.max(0.1, ...points.map((point) => Number(point.precip) || 0));\n"
L"  for (let index = 0; index < 24; ++index) {\n"
L"    const point = points[index] || { precip: 0 };\n"
L"    const bar = document.createElement('span');\n"
L"    const precipitation = Number(point.precip) || 0;\n"
L"    const intensity = precipitation >= 0.15 ? 'heavy'\n"
L"      : precipitation >= 0.05 ? 'rain' : precipitation > 0 ? 'drizzle' : 'none';\n"
L"    bar.className = 'minute-bar minute-bar-' + intensity;\n"
L"    bar.style.height = Math.max(2, Math.round(precipitation / max * 46)) + 'px';\n"
L"    bar.title = formatTime(point.time) + ' ' + formatNumber(point.precip, ' mm', 1);\n"
L"    bar.setAttribute('aria-label', bar.title);\n"
L"    elements.minuteChart.append(bar);\n"
L"  }\n"
L"  elements.minuteAxis.replaceChildren();\n"
L"  const axisLabels = isChinese()\n"
L"    ? ['\\u73b0\\u5728', '30 \\u5206\\u949f', '60 \\u5206\\u949f', '90 \\u5206\\u949f', '120 \\u5206\\u949f']\n"
L"    : ['Now', '30 min', '60 min', '90 min', '120 min'];\n"
L"  for (const label of axisLabels) {\n"
L"    const span = document.createElement('span');\n"
L"    span.textContent = label;\n"
L"    elements.minuteAxis.append(span);\n"
L"  }\n"
L"}\n"
L"\n"
L"function renderHourly() {\n"
L"  const value = labels();\n"
L"  const source = hourlySource();\n"
L"  let rows = Array.isArray(source.rows) ? source.rows : [];\n"
L"  if (source.provider === 'open-meteo') {\n"
L"    const current = currentSource();\n"
L"    const currentTime = current && current.item.time || '';\n"
L"    let start = rows.findIndex((row) => textValue(row.time) >= textValue(currentTime));\n"
L"    if (start < 0) start = 0;\n"
L"    rows = rows.slice(start, start + 24);\n"
L"  } else {\n"
L"    rows = rows.slice(0, 24);\n"
L"  }\n"
L"  elements.hourly.replaceChildren();\n"
L"  elements.hourlyLead.textContent = value.hourlyHint;\n"
L"  elements.hourlyNote.textContent = rows.length ? `${value.rainChance} | ${rows.length}h` : value.unavailable;\n"
L"  for (let index = 0; index < rows.length; ++index) {\n"
L"    const row = rows[index];\n"
L"    const hour = document.createElement('div');\n"
L"    hour.className = index === 0 ? 'hour current' : 'hour';\n"
L"    if (index === 0) hour.setAttribute('aria-current', 'true');\n"
L"    const time = document.createElement('div');\n"
L"    time.className = 'hour-time';\n"
L"    time.textContent = index === 0 && source.provider === 'open-meteo' ? value.now : formatTime(row.time);\n"
L"    const descriptionText = weatherText(row, source.provider);\n"
L"    const icon = document.createElement('i');\n"
L"    icon.className = 'weather-glyph';\n"
L"    icon.setAttribute('role', 'img');\n"
L"    icon.setAttribute('aria-label', descriptionText);\n"
L"    setWeatherGlyph(icon, row, source.provider);\n"
L"    const temperature = document.createElement('div');\n"
L"    temperature.className = 'hour-temp';\n"
L"    temperature.textContent = formatTemperature(row.temp);\n"
L"    const description = document.createElement('div');\n"
L"    description.className = 'hour-text';\n"
L"    description.textContent = descriptionText;\n"
L"    const probability = document.createElement('div');\n"
L"    probability.className = 'hour-prob';\n"
L"    const probabilityValue = Number(row.pop);\n"
L"    probability.classList.toggle('hour-prob-medium', Number.isFinite(probabilityValue) && probabilityValue >= 30 && probabilityValue < 60);\n"
L"    probability.classList.toggle('hour-prob-high', Number.isFinite(probabilityValue) && probabilityValue >= 60);\n"
L"    probability.textContent = row.pop === null || row.pop === undefined ? '--' : `${row.pop}%`;\n"
L"    probability.title = `${value.rainChance}: ${probability.textContent}`;\n"
L"    hour.append(time, icon, temperature, description, probability);\n"
L"    elements.hourly.append(hour);\n"
L"  }\n"
L"  if (!rows.length) {\n"
L"    const empty = document.createElement('div');\n"
L"    empty.className = 'empty';\n"
L"    empty.textContent = value.unavailable;\n"
L"    elements.hourly.append(empty);\n"
L"  }\n"
L"}\n"
L"\n"
L"function aqiColor(aqi) {\n"
L"  const value = Number(aqi);\n"
L"  if (value <= 50) return 'var(--green)';\n"
L"  if (value <= 100) return 'var(--amber)';\n"
L"  if (value <= 150) return 'var(--orange)';\n"
L"  return 'var(--red)';\n"
L"}\n"
L"\n"
L"function renderAirQuality() {\n"
L"  const value = labels();\n"
L"  const dataset = state.mode === 'qweather' && state.datasets.air;\n"
L"  const air = dataset && dataset.data;\n"
L"  if (!air) {\n"
L"    elements.airSection.hidden = state.mode !== 'qweather';\n"
L"    elements.airNote.textContent = value.unavailable;\n"
L"    elements.airLead.textContent = value.unavailable;\n"
L"    elements.aqiValue.textContent = '--';\n"
L"    elements.aqiCategory.textContent = '';\n"
L"    elements.aqiScaleDot.style.left = '0%';\n"
L"    elements.pollutants.replaceChildren();\n"
L"    elements.airAdvice.textContent = '';\n"
L"    elements.airAdvice.hidden = true;\n"
L"    return;\n"
L"  }\n"
L"  elements.airSection.hidden = false;\n"
L"  elements.airNote.textContent = air.primary ? `${value.primary}: ${air.primary}` : '';\n"
L"  elements.airLead.textContent = value.monitoring;\n"
L"  elements.aqiValue.textContent = air.aqi === null ? '--' : Math.round(air.aqi);\n"
L"  elements.aqiValue.style.color = aqiColor(air.aqi);\n"
L"  elements.aqiCategory.textContent = [air.category, air.level ? `${value.level} ${air.level}` : ''].filter(Boolean).join(' | ');\n"
L"  const aqiPosition = air.aqi === null ? 0 : Math.max(0, Math.min(100, Number(air.aqi) / 300 * 100));\n"
L"  elements.aqiScaleDot.style.left = `${aqiPosition}%`;\n"
L"  elements.pollutants.replaceChildren();\n"
L"  const primary = textValue(air.primary).toLowerCase();\n"
L"  for (const pollutant of (air.pollutants || []).slice(0, 6)) {\n"
L"    const item = document.createElement('div');\n"
L"    const pollutantCode = textValue(pollutant.code).toLowerCase();\n"
L"    const pollutantName = textValue(pollutant.name).toLowerCase();\n"
L"    const isPrimary = primary && (\n"
L"      primary === pollutantCode ||\n"
L"      primary === pollutantName ||\n"
L"      primary.includes(pollutantCode) ||\n"
L"      pollutantName.includes(primary)\n"
L"    );\n"
L"    item.className = isPrimary ? 'pollutant pollutant-primary' : 'pollutant';\n"
L"    const name = document.createElement('span');\n"
L"    name.className = 'pollutant-name';\n"
L"    name.textContent = pollutant.name || pollutant.code.toUpperCase();\n"
L"    const number = document.createElement('span');\n"
L"    number.className = 'pollutant-value';\n"
L"    number.textContent = formatNumber(pollutant.value, '', pollutant.code === 'co' ? 1 : 0);\n"
L"    const unit = document.createElement('span');\n"
L"    unit.className = 'pollutant-unit';\n"
L"    unit.textContent = formatMeasurementUnit(pollutant.unit);\n"
L"    item.append(name, number, unit);\n"
L"    elements.pollutants.append(item);\n"
L"  }\n"
L"  elements.airAdvice.textContent = air.advice || '';\n"
L"  elements.airAdvice.hidden = !elements.airAdvice.textContent;\n"
L"}\n"
L"\n"
L"function renderDaily() {\n"
L"  const value = labels();\n"
L"  const source = dailySource();\n"
L"  const rows = Array.isArray(source.rows) ? source.rows.slice(0, 5) : [];\n"
L"  elements.forecast.replaceChildren();\n"
L"  elements.dailyLead.textContent = value.dailyHint;\n"
L"  elements.dailyNote.textContent = rows.length ? '' : value.unavailable;\n"
L"  if (!rows.length) {\n"
L"    const empty = document.createElement('div');\n"
L"    empty.className = 'empty';\n"
L"    empty.textContent = value.unavailable;\n"
L"    elements.forecast.append(empty);\n"
L"    return;\n"
L"  }\n"
L"  const weekdayFormatter = new Intl.DateTimeFormat(state.language || 'en-US', { weekday: 'short' });\n"
L"  const dateFormatter = new Intl.DateTimeFormat(state.language || 'en-US', { month: 'numeric', day: 'numeric' });\n"
L"  const temperatures = rows.flatMap((row) => [row.tempMin, row.tempMax]).map(Number).filter(Number.isFinite);\n"
L"  const overallMin = temperatures.length ? Math.min(...temperatures) : 0;\n"
L"  const overallMax = temperatures.length ? Math.max(...temperatures) : 1;\n"
L"  const temperatureSpan = Math.max(1, overallMax - overallMin);\n"
L"  for (let index = 0; index < rows.length; ++index) {\n"
L"    const row = rows[index];\n"
L"    const day = document.createElement('div');\n"
L"    day.className = 'day';\n"
L"    const date = document.createElement('div');\n"
L"    date.className = 'day-date';\n"
L"    const name = document.createElement('div');\n"
L"    name.className = 'day-name';\n"
L"    const subdate = document.createElement('span');\n"
L"    subdate.className = 'day-subdate';\n"
L"    try {\n"
L"      const parsedDate = new Date(`${row.date}T12:00:00`);\n"
L"      name.textContent = index === 0 ? value.today : index === 1 ? value.tomorrow : weekdayFormatter.format(parsedDate);\n"
L"      subdate.textContent = dateFormatter.format(parsedDate);\n"
L"    } catch (error) {\n"
L"      name.textContent = row.date;\n"
L"      subdate.textContent = '';\n"
L"    }\n"
L"    date.append(name, subdate);\n"
L"    const weather = document.createElement('div');\n"
L"    weather.className = 'day-weather';\n"
L"    const descriptionText = weatherText(row, source.provider);\n"
L"    const icon = document.createElement('i');\n"
L"    icon.className = 'weather-glyph';\n"
L"    icon.setAttribute('role', 'img');\n"
L"    icon.setAttribute('aria-label', descriptionText);\n"
L"    setWeatherGlyph(icon, row, source.provider);\n"
L"    const text = document.createElement('div');\n"
L"    text.className = 'day-text';\n"
L"    text.textContent = descriptionText;\n"
L"    const probability = document.createElement('div');\n"
L"    probability.className = 'day-pop';\n"
L"    probability.textContent = row.pop === null || row.pop === undefined ? `${value.rain} --` : `${value.rain} ${row.pop}%`;\n"
L"    probability.setAttribute('aria-label', probability.textContent);\n"
L"    weather.append(icon, text);\n"
L"    const range = document.createElement('div');\n"
L"    range.className = 'day-range';\n"
L"    const low = document.createElement('span');\n"
L"    low.className = 'day-low';\n"
L"    low.textContent = formatTemperatureShort(row.tempMin);\n"
L"    const track = document.createElement('div');\n"
L"    track.className = 'day-track';\n"
L"    const fill = document.createElement('span');\n"
L"    fill.className = 'day-range-fill';\n"
L"    const min = Number(row.tempMin);\n"
L"    const max = Number(row.tempMax);\n"
L"    if (Number.isFinite(min) && Number.isFinite(max)) {\n"
L"      let left = Math.max(0, Math.min(100, (min - overallMin) / temperatureSpan * 100));\n"
L"      const width = Math.max(8, Math.min(100, (max - min) / temperatureSpan * 100));\n"
L"      left = Math.min(left, 100 - width);\n"
L"      fill.style.left = `${left}%`;\n"
L"      fill.style.width = `${width}%`;\n"
L"    } else {\n"
L"      fill.hidden = true;\n"
L"    }\n"
L"    track.append(fill);\n"
L"    const high = document.createElement('span');\n"
L"    high.className = 'day-high';\n"
L"    high.textContent = formatTemperatureShort(row.tempMax);\n"
L"    range.append(low, track, high);\n"
L"    day.append(date, weather, probability, range);\n"
L"    elements.forecast.append(day);\n"
L"  }\n"
L"}\n"
L"\n"
L"function collectSources() {\n"
L"  const sources = [];\n"
L"  function append(values) {\n"
L"    for (const value of values || []) {\n"
L"      const clean = textValue(value);\n"
L"      if (clean && !sources.some((existing) => existing.toLowerCase() === clean.toLowerCase())) sources.push(clean);\n"
L"    }\n"
L"  }\n"
L"  if (state.mode === 'qweather') {\n"
L"    append(['QWeather']);\n"
L"    for (const name of DATASET_NAMES) {\n"
L"      const dataset = state.datasets[name];\n"
L"      append(dataset && dataset.refer && dataset.refer.sources);\n"
L"      append(dataset && dataset.data && dataset.data.refer && dataset.data.refer.sources);\n"
L"    }\n"
L"  } else {\n"
L"    append(['Open-Meteo', state.place && state.place.source]);\n"
L"  }\n"
L"  if (state.mode === 'qweather') append([state.place && state.place.source]);\n"
L"  if (state.place && /^Direct IP/i.test(textValue(state.place.source))) append(['ipwho.is']);\n"
L"  return sources;\n"
L"}\n"
L"\n"
L"function qweatherAttributionUrl() {\n"
L"  for (const name of DATASET_NAMES) {\n"
L"    const links = state.datasets[name] && state.datasets[name].refer && state.datasets[name].refer.attributions;\n"
L"    for (const link of links || []) {\n"
L"      if (/^https:\\/\\/developer\\.qweather\\.com\\/attribution\\.html(?:[?#].*)?$/i.test(link)) return link;\n"
L"    }\n"
L"  }\n"
L"  return 'https://developer.qweather.com/attribution.html';\n"
L"}\n"
L"\n"
L"function renderSources() {\n"
L"  const value = labels();\n"
L"  elements.poweredBy.replaceChildren();\n"
L"  const attribution = document.createElement('span');\n"
L"  attribution.textContent = 'QWeather Icons';\n"
L"  if (state.mode === 'qweather') {\n"
L"    const link = document.createElement('a');\n"
L"    link.href = qweatherAttributionUrl();\n"
L"    link.textContent = value.powered;\n"
L"    elements.poweredBy.append(link, document.createTextNode(' · '), attribution);\n"
L"  } else {\n"
L"    const link = document.createElement('a');\n"
L"    link.href = 'https://open-meteo.com/';\n"
L"    link.textContent = 'Open-Meteo';\n"
L"    elements.poweredBy.append(link, document.createTextNode(' · '), attribution);\n"
L"  }\n"
L"  const sources = collectSources();\n"
L"  elements.sourceList.textContent = sources.length ? `${value.sources}: ${sources.join(', ')}` : '';\n"
L"}\n"
L"\n"
L"function displayWindSpeed(value) {\n"
L"  if (value === null || value === undefined || !Number.isFinite(Number(value))) return null;\n"
L"  return state.unit ? Number(value) / 1.609344 : Number(value);\n"
L"}\n"
L"\n"
L"function renderHero(item) {\n"
L"  const value = labels();\n"
L"  const daily = dailySource().rows[0];\n"
L"  const dailyRange = daily && daily.tempMin !== null && daily.tempMax !== null\n"
L"    ? value.today + ' ' + formatTemperatureShort(daily.tempMin) + ' - ' + formatTemperatureShort(daily.tempMax)\n"
L"    : '';\n"
L"  elements.heroRange.textContent = dailyRange;\n"
L"  elements.heroRange.hidden = !dailyRange;\n"
L"\n"
L"  const minute = state.mode === 'qweather' && state.datasets.minutely && state.datasets.minutely.data;\n"
L"  const summary = minute && minute.available !== false ? textValue(minute.summary) : '';\n"
L"  elements.heroSummary.textContent = summary;\n"
L"  elements.heroSummary.hidden = !summary;\n"
L"\n"
L"  const context = [];\n"
L"  if (item.feels !== null && item.feels !== undefined) {\n"
L"    context.push(value.feels + ' ' + formatTemperature(item.feels));\n"
L"  }\n"
L"  if (item.humidity !== null && item.humidity !== undefined) {\n"
L"    context.push(value.humidity + ' ' + formatNumber(item.humidity, '%'));\n"
L"  }\n"
L"  const windSpeed = displayWindSpeed(item.windSpeed);\n"
L"  if (windSpeed !== null) {\n"
L"    context.push((item.windDir ? formatWindDirection(item.windDir) + ' ' : '') +\n"
L"      formatNumber(windSpeed, state.unit ? ' mph' : ' km/h'));\n"
L"  }\n"
L"  elements.heroContext.textContent = context.join(' \\u00b7 ');\n"
L"  elements.heroContext.hidden = !elements.heroContext.textContent;\n"
L"}\n"
L"\n"
L"function renderMetrics(item) {\n"
L"  const value = labels();\n"
L"  elements.feels.textContent = formatTemperature(item.feels);\n"
L"  elements.humidity.textContent = formatNumber(item.humidity, '%');\n"
L"  elements.wind.textContent = (item.windDir ? formatWindDirection(item.windDir) + ' ' : '') +\n"
L"    formatNumber(displayWindSpeed(item.windSpeed), state.unit ? ' mph' : ' km/h');\n"
L"  const precipitation = item.precip === null || item.precip === undefined\n"
L"    ? null\n"
L"    : state.unit ? Number(item.precip) / 25.4 : Number(item.precip);\n"
L"  const visibility = item.visibility === null || item.visibility === undefined\n"
L"    ? null\n"
L"    : state.unit ? Number(item.visibility) / 1.609344 : Number(item.visibility);\n"
L"  elements.precip.textContent = formatNumber(precipitation, state.unit ? ' in' : ' mm', state.unit ? 2 : 1);\n"
L"  elements.visibility.textContent = formatNumber(visibility, state.unit ? ' mi' : ' km', 0);\n"
L"\n"
L"  const temp = displayTemperatureValue(item.temp);\n"
L"  const feels = displayTemperatureValue(item.feels);\n"
L"  if (temp === null || feels === null) {\n"
L"    elements.feelsSub.textContent = '';\n"
L"  } else {\n"
L"    const delta = Math.round((feels - temp) * 10) / 10;\n"
L"    elements.feelsSub.textContent = Math.abs(delta) < 1\n"
L"      ? value.feelsClose\n"
L"      : delta > 0 ? value.feelsWarm + ' +' + delta + String.fromCharCode(176)\n"
L"        : value.feelsCool + ' ' + delta + String.fromCharCode(176);\n"
L"  }\n"
L"\n"
L"  const humidity = item.humidity === null || item.humidity === undefined ? null : Number(item.humidity);\n"
L"  elements.humidityMeter.style.width = humidity === null ? '0%' : Math.max(0, Math.min(100, humidity)) + '%';\n"
L"  elements.humiditySub.textContent = humidity === null\n"
L"    ? ''\n"
L"    : humidity < 35 ? value.humidityDry : humidity >= 75 ? value.humidityHigh : value.humidityComfort;\n"
L"\n"
L"  elements.windSub.textContent = item.windDir ? value.observed + ': ' + formatWindDirection(item.windDir) : '';\n"
L"  elements.precipSub.textContent = precipitation === null ? '' : value.observed;\n"
L"  elements.visibilitySub.textContent = visibility === null\n"
L"    ? ''\n"
L"    : visibility >= 10 ? value.visibilityGood : visibility >= 5 ? value.visibilityFair : value.visibilityLow;\n"
L"}\n"
L"\n"
L"function renderWeather() {\n"
L"  const current = currentSource();\n"
L"  if (!current) {\n"
L"    if (state.status === 'error') setError();\n"
L"    return;\n"
L"  }\n"
L"  const value = labels();\n"
L"  const item = current.item;\n"
L"  document.documentElement.lang = state.language || 'en';\n"
L"  setStaticLabels();\n"
L"  elements.location.textContent = state.place && state.place.name || state.location;\n"
L"  const resolvedParts = [state.place && state.place.city, state.place && (state.place.province || state.place.country)]\n"
L"    .map((part) => textValue(part))\n"
L"    .filter((part, index, array) => part && array.indexOf(part) === index && part !== elements.location.textContent);\n"
L"  const locationSource = textValue(state.place && state.place.source);\n"
L"  if (/^Windows Location/i.test(locationSource)) {\n"
L"    resolvedParts.push(value.windowsLocationSource);\n"
L"  } else if (/^Direct IP/i.test(locationSource)) {\n"
L"    resolvedParts.push(value.directIpSource);\n"
L"  }\n"
L"  elements.resolved.textContent = resolvedParts.join(' \\u00b7 ');\n"
L"  renderProviderState();\n"
L"  elements.temperature.textContent = Math.round(displayTemperatureValue(item.temp));\n"
L"  elements.unit.textContent = tempUnit();\n"
L"  elements.condition.textContent = weatherText(item, current.provider);\n"
L"  const updateTime = item.time || current.fetchedAt;\n"
L"  elements.updated.textContent = updateTime ? `${value.updated} ${formatTime(updateTime)}` : '';\n"
L"  renderUpdateStatus(current);\n"
L"  renderHero(item);\n"
L"  renderMetrics(item);\n"
L"  setWeatherGlyph(elements.currentGlyph, item, current.provider);\n"
L"  elements.currentGlyph.setAttribute('aria-label', weatherText(item, current.provider));\n"
L"  drawWeatherIcon(elements.currentIcon, item, current.provider);\n"
L"  renderAlerts();\n"
L"  renderMinuteForecast();\n"
L"  renderHourly();\n"
L"  renderAirQuality();\n"
L"  renderDaily();\n"
L"  renderSources();\n"
L"}\n"
L"\n"
L"function scheduleRenderAndCapture(captureTaskbar) {\n"
L"  if (renderTimer) clearTimeout(renderTimer);\n"
L"  renderTimer = setTimeout(() => {\n"
L"    renderTimer = null;\n"
L"    renderWeather();\n"
L"    if (captureTaskbar || hasCurrentData()) notifyHost();\n"
L"  }, 0);\n"
L"}\n"
L"\n"
L"function notifyHost() {\n"
L"  if (state.notifyTimer) clearTimeout(state.notifyTimer);\n"
L"  state.notifyTimer = setTimeout(() => {\n"
L"    state.notifyTimer = null;\n"
L"    try {\n"
L"      if (window.chrome && window.chrome.webview) window.chrome.webview.postMessage('ep_weather_updated');\n"
L"    } catch (error) {\n"
L"      // The standalone verifier and visual tests do not provide a WebView host.\n"
L"    }\n"
L"  }, 300);\n"
L"}\n"
L"\n"
L"function imageHex(width, height) {\n"
L"  const outputWidth = Math.max(1, Math.min(64, Number(width) || 32));\n"
L"  const outputHeight = Math.max(1, Math.min(64, Number(height) || outputWidth));\n"
L"  const source = elements.currentIcon;\n"
L"  const sourceContext = source.getContext('2d', { willReadFrequently: true });\n"
L"  const pixels = sourceContext.getImageData(0, 0, source.width, source.height).data;\n"
L"  let left = source.width, top = source.height, right = -1, bottom = -1;\n"
L"  for (let y = 0; y < source.height; ++y) {\n"
L"    for (let x = 0; x < source.width; ++x) {\n"
L"      if (pixels[(y * source.width + x) * 4 + 3] > 8) {\n"
L"        left = Math.min(left, x); top = Math.min(top, y);\n"
L"        right = Math.max(right, x); bottom = Math.max(bottom, y);\n"
L"      }\n"
L"    }\n"
L"  }\n"
L"  const canvas = document.createElement('canvas');\n"
L"  canvas.width = outputWidth; canvas.height = outputHeight;\n"
L"  const context = canvas.getContext('2d', { willReadFrequently: true });\n"
L"  if (right >= left && bottom >= top) {\n"
L"    const padding = 2;\n"
L"    left = Math.max(0, left - padding); top = Math.max(0, top - padding);\n"
L"    right = Math.min(source.width - 1, right + padding); bottom = Math.min(source.height - 1, bottom + padding);\n"
L"    const sourceWidth = right - left + 1;\n"
L"    const sourceHeight = bottom - top + 1;\n"
L"    const scale = Math.min((outputWidth - 2) / sourceWidth, (outputHeight - 2) / sourceHeight);\n"
L"    const destinationWidth = Math.max(1, Math.round(sourceWidth * scale));\n"
L"    const destinationHeight = Math.max(1, Math.round(sourceHeight * scale));\n"
L"    context.drawImage(source, left, top, sourceWidth, sourceHeight,\n"
L"      Math.floor((outputWidth - destinationWidth) / 2), Math.floor((outputHeight - destinationHeight) / 2),\n"
L"      destinationWidth, destinationHeight);\n"
L"  }\n"
L"  const output = context.getImageData(0, 0, outputWidth, outputHeight).data;\n"
L"  const digits = '0123456789abcdef';\n"
L"  let result = '';\n"
L"  for (let index = 0; index < output.length; index += 4) {\n"
L"    const alpha = output[index + 3];\n"
L"    const values = [\n"
L"      Math.round(output[index + 2] * alpha / 255),\n"
L"      Math.round(output[index + 1] * alpha / 255),\n"
L"      Math.round(output[index] * alpha / 255),\n"
L"      alpha\n"
L"    ];\n"
L"    for (const value of values) result += digits[(value >> 4) & 15] + digits[value & 15];\n"
L"  }\n"
L"  return result;\n"
L"}\n"
L"\n"
L"// Keep the private response field stable; the native host owns the viewport size.\n"
L"const NATIVE_VIEWPORT_HEIGHT = 367;\n"
L"\n"
L"function safeField(value) {\n"
L"  return textValue(value).replace(/[#\"]/g, ' ');\n"
L"}\n"
L"\n"
L"window.epWeatherGetData = function(location, language, unit, width, height, apiHost, locationMode) {\n"
L"  const cleanLocation = textValue(location);\n"
L"  const cleanLanguage = textValue(language, 'en-US') || 'en-US';\n"
L"  const selectedUnit = Number(unit) ? 1 : 0;\n"
L"  const cleanHost = validQWeatherHost(apiHost) ? textValue(apiHost).toLowerCase() : '';\n"
L"  const numericLocationMode = Number(locationMode);\n"
L"  const selectedLocationMode = [LOCATION_MODE_WINDOWS, LOCATION_MODE_LEGACY_PRECISE,\n"
L"    LOCATION_MODE_DIRECT_IP, LOCATION_MODE_MANUAL].includes(numericLocationMode)\n"
L"    ? numericLocationMode : LOCATION_MODE_WINDOWS;\n"
L"  const key = `${cleanLocation}\\n${cleanLanguage}\\n${selectedUnit}\\n${cleanHost}\\n${selectedLocationMode}`;\n"
L"  state.iconWidth = width;\n"
L"  state.iconHeight = height;\n"
L"  if (state.key !== key) {\n"
L"    state.key = key;\n"
L"    state.location = cleanLocation;\n"
L"    state.language = cleanLanguage;\n"
L"    state.unit = selectedUnit;\n"
L"    state.apiHost = cleanHost;\n"
L"    state.locationMode = selectedLocationMode;\n"
L"    resetState();\n"
L"    initializeWeather(state.generation);\n"
L"    return 'ep_pending';\n"
L"  }\n"
L"  refreshDue(false).catch(() => {});\n"
L"  if (state.status === 'loading' || state.status === 'idle') return 'ep_pending';\n"
L"  const current = currentSource();\n"
L"  if (state.status !== 'ready' || !current) return 'ep_error';\n"
L"  const item = current.item;\n"
L"  return `${document.documentElement.getAttribute('dir') || 'ltr'}#${NATIVE_VIEWPORT_HEIGHT}#${Math.round(displayTemperatureValue(item.temp))}#${tempUnit()}#${safeField(weatherText(item, current.provider))}#${safeField(state.place && state.place.name || state.location)}#${imageHex(width, height)}`;\n"
L"};\n"
L"\n"
L"window.epWeatherRefresh = refreshWeatherNow;\n"
L"\n"
L"if (elements.themeButton) elements.themeButton.addEventListener('click', toggleTheme);\n"
L"if (elements.refreshButton) {\n"
L"  elements.refreshButton.addEventListener('click', () => {\n"
L"    refreshWeatherNow().catch(() => setRefreshNotice(labels().refreshFailed));\n"
L"  });\n"
L"}\n"
L"\n"
L"if (window.__epWeatherTestMode) {\n"
L"  window.__epWeatherTest = Object.freeze({\n"
L"    state,\n"
L"    normalizeQCurrent,\n"
L"    normalizeQHourly,\n"
L"    normalizeQDaily,\n"
L"    normalizeQMinutely,\n"
L"    normalizeQAlerts,\n"
L"    normalizeQAir,\n"
L"    normalizeOpenMeteo,\n"
L"    normalizeDirectIpLocation,\n"
L"    normalizeWindowsLocation,\n"
L"    validQWeatherHost,\n"
L"    refreshDue,\n"
L"    DATASET_TTL,\n"
L"    weatherIconCode,\n"
L"    weatherIconGlyph,\n"
L"    weatherIconFontReady: () => weatherIconFontLoaded,\n"
L"    renderWeather,\n"
L"    refreshWeatherNow,\n"
L"    toggleTheme\n"
L"  });\n"
L"}\n"
L"\n"
L"setLoading();\n"
L"initializeWeatherIconFont();\n"
L"})();\n"
L"</script>\n"
L"</body>\n"
L"</html>\n"
;
#endif
